/**
 * OUR MEASURED EXPERIMENT — T-CAD synthetic-simulator results.
 * Generated by scripts/import_research_data.py from research-data/measured/
 * (results/ of the T-CAD repository, last complete run). Do not hand-edit numbers here.
 *
 * Scope: 45 held-out scenarios from a PyGame/NumPy simulator with bounded synthetic
 * message-level contradictions. NOT Adv-OPV2V and NOT comparable to Zhang et al. (2024).
 */
import data from "./data/measured.generated.json";

export type ConfigId = "A0" | "A1" | "A2" | "A3" | "A4" | "A5" | "A5-LR";
export interface Ci {
  est: number;
  lo: number;
  hi: number;
  nUnits: number;
  nRows: number;
  nPos: number;
  nNeg: number;
}
export type MetricId = "tpr" | "fpr" | "precision" | "f1" | "balancedAccuracy" | "auroc" | "auprc";

export const measured = data as unknown as {
  provenance: {
    source: string;
    simulator: string;
    testScenarios: number;
    reportRows: number;
    positiveRows: number;
    positiveFraction: number;
    splits: Record<string, { ok: number; total: number }>;
    ciMethod: string;
    hardware: string;
    wallTimeS: number;
    notComparableTo: string;
  };
  configs: ConfigId[];
  descriptions: Record<ConfigId, string>;
  report: Record<ConfigId, Record<MetricId, Ci>>;
  frame: Record<ConfigId, Record<MetricId, Ci>>;
  comparisons: { base: string; config: ConfigId; metric: MetricId; a: number; b: number; diff: number; lo: number; hi: number; direction: string; seedsBetter: number; seedsTotal: number }[];
  contributions: { step: string; component: string; metric: string; diff: number; lo: number; hi: number; direction: string }[];
  events: Record<ConfigId, { episodes: number; detectionRate: number; meanDelayS: number; medianDelayS: number }>;
  benignEvents: Record<ConfigId, { episodes: number; falseAlarmRate: number }>;
  fprByCondition: Record<ConfigId, Record<string, { fpr: number; nNeg: number }>>;
  latency: Record<ConfigId, { meanMs: number; p50Ms: number; p95Ms: number; maxMs: number; egoFrames: number; fracUnder100ms: number }>;
  calibrationMetrics: { model: string; n: number; brier: number; nll: number; ece: number; accuracy: number }[];
  calibrationParams: {
    priorOccupied: number;
    rho: number;
    pFreeToOcc: number;
    pOccToFree: number;
    rangeBinsM: number[];
    likelihoodTable: number[][][];
    source: string;
  };
  thresholds: { perConfigM2: Record<string, number>; strongCadM2: number; ruleTau4M2: number; lrTau: number; source: string };
  hmmByFamily: { family: string; metric: string; delta: number; lo: number; hi: number; betterIf: string; comparison: string }[];
  variants: Record<string, Partial<Record<ConfigId, { est: number; lo: number; hi: number }>>>;
  byFamily: Record<string, Partial<Record<ConfigId, Record<string, number>>>>;
  researchQuestions: { question: string; answer: string; evidence: string; status: string }[];
  robustness: {
    experiment: string;
    param: string;
    value: number | string;
    variant: string;
    config: ConfigId;
    runs: number;
    auroc: number;
    aurocLo: number;
    aurocHi: number;
    tpr: number;
    tprLo: number;
    tprHi: number;
    fpr: number;
    fprLo: number;
    fprHi: number;
    eventDetection: number | null;
    meanDelayS: number | null;
  }[];
  runtimeScaling: { sweep: string; value: number; config: ConfigId; p95Ms: number; meanMs: number; cells: number }[];
  figures: { file: string; id: string; kind: string; experiment: string; scenario: string; description: string; metrics: string }[];
};

export const configNames: Record<ConfigId, string> = {
  A0: "CAD baseline",
  A1: "+ calibrated observations",
  A2: "+ Bayesian LOO corroboration",
  A3: "CAD-HMM (per-source)",
  A4: "Bayes + HMM (fused, LOO)",
  A5: "T-CAD rule",
  "A5-LR": "T-CAD logistic",
};

export const metricLabels: Record<MetricId, string> = {
  tpr: "TPR @ frozen threshold",
  fpr: "FPR @ frozen threshold",
  precision: "Precision",
  f1: "F1",
  balancedAccuracy: "Balanced accuracy",
  auroc: "AUROC",
  auprc: "AUPRC",
};

/** Source caption used under every measured chart. */
export const measuredSource = (file: string) => `research-data/measured/${file} · ${measured.provenance.testScenarios} test scenarios · 95% scenario-bootstrap CI`;

export const pct = (v: number | null | undefined, d = 1) => (v === null || v === undefined ? "—" : `${(v * 100).toFixed(d)}%`);
